// Type declarations for vite-imagetools query imports.
declare module "*&as=srcset" {
  const src: string;
  export default src;
}
declare module "*&format=avif" {
  const src: string;
  export default src;
}
declare module "*&format=webp" {
  const src: string;
  export default src;
}
declare module "*&format=jpg" {
  const src: string;
  export default src;
}
